"""
linalg.py - A pure Python library for basic matrix and vector operations
Supported operations:
- Addition, Multiplication, Transpose
- Determinant and Inverse (Gauss-Jordan for square matrices)
- Solving linear equation systems
- Input validation for all routines
"""
from copy import deepcopy

class MatrixError(Exception):
    """Custom exception for matrix errors."""
    pass

def is_vector(obj):
    return isinstance(obj, list) and all(is_number(x) for x in obj)

def is_number(x):
    return isinstance(x, (int, float, complex))

def is_matrix(obj):
    return (
        isinstance(obj, list)
        and len(obj) > 0
        and all(isinstance(row, list) for row in obj)
        and all(is_number(el) for row in obj for el in row)
        and len(set(len(row) for row in obj)) == 1
    )

def shape(mat):
    if is_vector(mat):
        return (len(mat),)
    if is_matrix(mat):
        return (len(mat), len(mat[0]))
    raise MatrixError("Invalid argument for shape: {}".format(mat))

def add(a, b):
    """Add matrices or vectors of the same shape."""
    if shape(a) != shape(b):
        raise MatrixError("Shapes do not match for addition.")
    if is_vector(a):
        return [a[i] + b[i] for i in range(len(a))]
    if is_matrix(a):
        return [[a[i][j] + b[i][j] for j in range(len(a[0]))] for i in range(len(a))]
    raise MatrixError("Inputs must be vectors or matrices.")

def transpose(mat):
    """Transpose a matrix."""
    if is_vector(mat):
        return [[x] for x in mat]
    if is_matrix(mat):
        return [[mat[i][j] for i in range(len(mat))] for j in range(len(mat[0]))]
    raise MatrixError("Invalid input for transpose.")

def multiply(a, b):
    """Multiply matrices or matrix-vector, or scalar with matrix/vector."""
    # Scalar * matrix/vector
    if is_number(a):
        if is_vector(b):
            return [a * x for x in b]
        if is_matrix(b):
            return [[a * x for x in row] for row in b]
        raise MatrixError("Cannot multiply scalar with non-matrix/vector.")
    if is_number(b):
        return multiply(b, a)
    # Matrix * vector
    if is_matrix(a) and is_vector(b):
        rows, cols = shape(a)
        if cols != len(b):
            raise MatrixError("Matrix columns must match vector size.")
        return [sum(a[i][j]*b[j] for j in range(cols)) for i in range(rows)]
    # Matrix * matrix
    if is_matrix(a) and is_matrix(b):
        ar, ac = shape(a)
        br, bc = shape(b)
        if ac != br:
            raise MatrixError("Matrix shapes are not aligned for multiplication.")
        return [[sum(a[i][k]*b[k][j] for k in range(ac)) for j in range(bc)] for i in range(ar)]
    raise MatrixError("Unsupported multiply types.")

def _get_minor(mat, i, j):
    return [row[:j] + row[j+1:] for idx, row in enumerate(mat) if idx != i]

def determinant(mat):
    """Compute the determinant of a square matrix recursively."""
    if not is_matrix(mat):
        raise MatrixError("Input is not a matrix.")
    r, c = shape(mat)
    if r != c:
        raise MatrixError("Determinant is defined only for square matrices.")
    # Base cases
    if r == 1:
        return mat[0][0]
    if r == 2:
        return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
    det = 0
    for j in range(c):
        det += ((-1)**j) * mat[0][j] * determinant(_get_minor(mat, 0, j))
    return det

def inverse(mat, tol=1e-12):
    """Compute the inverse of a square matrix using Gauss-Jordan elimination."""
    if not is_matrix(mat):
        raise MatrixError("Input is not a matrix.")
    n, m = shape(mat)
    if n != m:
        raise MatrixError("Matrix must be square for inversion.")
    A = deepcopy(mat)
    I = [[float(i==j) for j in range(n)] for i in range(n)]
    for col in range(n):
        # Find pivot
        pivot_row = None
        for row in range(col, n):
            if abs(A[row][col]) > tol:
                pivot_row = row
                break
        if pivot_row is None:
            raise MatrixError("Matrix is singular or near-singular.")
        if pivot_row != col:
            A[col], A[pivot_row] = A[pivot_row], A[col]
            I[col], I[pivot_row] = I[pivot_row], I[col]
        fac = A[col][col]
        A[col] = [x/fac for x in A[col]]
        I[col] = [x/fac for x in I[col]]
        # Eliminate
        for row in range(n):
            if row != col:
                fac = A[row][col]
                A[row] = [a - fac*b for a,b in zip(A[row], A[col])]
                I[row] = [a - fac*b for a,b in zip(I[row], I[col])]
    return I

def solve(mat, vec, tol=1e-12):
    """Solve Ax = b for x, where A is a square matrix and b a vector."""
    if not is_matrix(mat):
        raise MatrixError("First argument is not a matrix.")
    n, m = shape(mat)
    if n != m:
        raise MatrixError("Can only solve square systems.")
    if not is_vector(vec) or len(vec) != n:
        raise MatrixError("Right-hand side dimensions do not match.")
    # Augment
    A = deepcopy(mat)
    b = list(vec)
    for col in range(n):
        # Find pivot
        pivot_row = None
        for row in range(col, n):
            if abs(A[row][col]) > tol:
                pivot_row = row
                break
        if pivot_row is None:
            raise MatrixError("System is singular or near-singular.")
        if pivot_row != col:
            A[col], A[pivot_row] = A[pivot_row], A[col]
            b[col], b[pivot_row] = b[pivot_row], b[col]
        fac = A[col][col]
        A[col] = [x/fac for x in A[col]]
        b[col] = b[col]/fac
        for row in range(n):
            if row != col:
                fac = A[row][col]
                A[row] = [a - fac*bj for a, bj in zip(A[row], A[col])]
                b[row] = b[row] - fac * b[col]
    return b

# End of linalg.py
